import json
BAS = [
 ("bas01",1,"What did you think of the new library?","The study rooms on the third floor are much quieter than before.",["the study rooms","on the third floor","are","much quieter","than before"],"Vergleich: Komparativ + than (much quieter than)."),
 ("bas02",2,"Why weren't you at the meeting yesterday?","I didn't know that it had been moved to the afternoon.",["I","didn't know","that","it had been","moved","to the afternoon"],"Vorvergangenheit im Passiv: had been + Partizip."),
 ("bas03",2,"Do you know when the assignment is due?","The professor said it has to be submitted by Friday.",["the professor","said","it","has to be","submitted","by Friday"],"Passiv mit Modal: has to be + Partizip."),
 ("bas04",2,"Where should we meet before the concert?","Let's meet at the café where we had lunch last week.",["let's meet","at the café","where","we had","lunch","last week"],"Relativsatz mit where direkt hinter dem Ort."),
 ("bas05",3,"Have you decided which course to take?","I'm still trying to figure out which one fits my schedule.",["I'm still","trying to","figure out","which one","fits","my schedule"],"Indirekte Frage: which one + Verb, keine Inversion."),
 ("bas06",2,"How was your internship this summer?","It was the most useful experience I have ever had.",["it was","the most","useful experience","I","have ever","had"],"Superlativ + Relativsatz ohne that: the most … I have ever had."),
 ("bas07",3,"Can you help me move on Saturday?","I would if I didn't have to work that day.",["I would","if","I","didn't have","to work","that day"],"Irrealer if-Satz: would …, if + Past."),
 ("bas08",2,"Why is the cafeteria so crowded today?","They are offering free coffee to anyone who brings a mug.",["they are offering","free coffee","to anyone","who","brings","a mug"],"Relativsatz who + Verb mit -s (anyone = Singular)."),
 ("bas09",1,"Did you finish the lab report?","Not yet, but I should be done by tonight.",["not yet","but","I","should be","done","by tonight"],"Modal + be + Partizip: should be done."),
 ("bas10",3,"What did the advisor tell you?","She asked me whether I had thought about studying abroad.",["she asked me","whether","I","had thought","about","studying abroad"],"Indirekte Frage: whether + Subjekt + Verb; Präposition + -ing."),
 ("bas11",1,"Is the bookstore still open?","I think it closes at six on weekdays.",["I think","it","closes","at six","on weekdays"],"Zeitangaben: at + Uhrzeit, on + Tage."),
 ("bas12",2,"Who is giving the guest lecture?","It is a scientist who worked for NASA for twenty years.",["it is","a scientist","who","worked","for NASA","for twenty years"],"Relativsatz direkt hinter dem Nomen (a scientist who …)."),
 ("bas13",1,"How do you usually get to campus?","I usually ride my bike unless it is raining.",["I","usually","ride my bike","unless","it is","raining"],"Häufigkeitsadverb vor dem Vollverb (I usually ride)."),
 ("bas14",3,"Why did you choose this university?","Its engineering program is known for its close ties to industry.",["its engineering program","is known","for","its close ties","to industry"],"Feste Verbindung: be known for; ties to."),
 ("bas15",1,"Can you tell me where the registrar's office is?","It is located on the second floor of the administration building.",["it is","located","on the second floor","of","the administration building"],"be located on the … floor."),
 ("bas16",1,"What should I bring to the job fair?","You should bring several copies of your resume.",["you should","bring","several copies","of","your resume"],"Modal + Grundform: should bring."),
 ("bas17",2,"Has the professor graded our exams yet?","She said the results would be posted next Monday.",["she said","the results","would be","posted","next Monday"],"Indirekte Rede: will → would; Passiv would be posted."),
 ("bas18",3,"Why are you studying in the hallway?","The room I reserved was already being used by another group.",["the room","I reserved","was already","being used","by","another group"],"Passiv Verlaufsform: was being used."),
 ("bas19",3,"Are you going to the conference in March?","Only if my department agrees to pay for the trip.",["only if","my department","agrees","to pay","for the trip"],"agree + to + Grundform; Present Simple nach if."),
 ("bas20",3,"What surprised you most about the city?","What surprised me most was how friendly everyone was.",["what surprised me","most","was","how friendly","everyone","was"],"Cleft Sentence What … was + indirekte Frage how friendly everyone was."),
 ("bas21",2,"Did you enjoy the book I lent you?","I enjoyed it so much that I finished it in two days.",["I enjoyed it","so much","that","I finished it","in two days"],"so … that = so sehr, dass."),
 ("bas22",2,"Should we take the train or drive?","Taking the train would be faster than driving in this traffic.",["taking the train","would be","faster","than","driving","in this traffic"],"-ing-Form als Subjekt (Taking the train …)."),
 ("bas23",3,"Why did the event get canceled?","Not enough people had signed up by the deadline.",["not enough","people","had signed up","by","the deadline"],"by + Zeitpunkt → Past Perfect (had signed up)."),
 ("bas24",1,"Do you mind if I open the window?","Not at all, as long as it doesn't get too cold.",["not at all","as long as","it","doesn't get","too cold"],"as long as + Present Simple = solange."),
]
EMAIL = [
 {"id":"em01","level":2,"situation":"You recently bought a used bicycle through your university's online marketplace. When it arrived, you discovered that the brakes do not work properly, although the listing described the bicycle as being in \"excellent condition.\"","recipient":"the seller, Chris","tasks":["Explain why you chose to buy this bicycle.","Describe the problem with the bicycle.","Suggest a way to resolve the situation."]},
 {"id":"em02","level":2,"situation":"You are taking an online course. The course website says that the final project can be completed alone or in pairs. You would like to work with a classmate who is enrolled in a different section of the same course.","recipient":"your instructor, Dr. Patel","tasks":["Explain your idea for the project.","Explain why you want to work with this classmate.","Ask whether this arrangement is allowed."]},
 {"id":"em03","level":2,"situation":"Your neighbor in your apartment building often plays loud music late at night. You have important exams next week and need to sleep well.","recipient":"your neighbor, Alex","tasks":["Introduce yourself and explain why you are writing.","Describe how the noise affects you.","Suggest a solution that would work for both of you."]},
 {"id":"em04","level":2,"situation":"Last week you attended a free career workshop organized by your university. You found it very helpful, but one session ran out of time before the speaker could answer questions from the audience.","recipient":"the workshop organizer, Ms. Romero","tasks":["Explain what you found most helpful.","Describe the problem with the session.","Suggest an improvement for future workshops."]},
 {"id":"em05","level":2,"situation":"A friend who lives in another city is visiting you next month and has asked for advice about what to do during the visit. You have just started a new part-time job and will have to work on one of the days of the visit.","recipient":"your friend, Jamie","tasks":["Recommend two things to do in your city.","Explain the problem with your schedule.","Suggest how you could still spend time together."]},
 {"id":"em06","level":2,"situation":"Two weeks ago, you ordered a textbook from an online store for a class that starts on Monday. The store's website says the order has been shipped, but you have not received it, and the tracking number does not work.","recipient":"the store's customer service team","tasks":["Give the details of your order.","Explain why you need the book urgently.","Ask for a specific solution."]},
]
DISC = [
 {"id":"di01","level":2,"course":"education","professor":{"name":"Dr. Lin","text":"Many universities now record their lectures and post them online. Some educators believe this helps students learn, while others worry that it reduces class attendance and engagement. Should universities record all lectures and make them available online? Why or why not?"},
  "students":[{"name":"Mia","text":"I think recording lectures is essential. Students who are sick or have to work can still keep up, and everyone can rewatch difficult parts before exams. Learning shouldn't depend on being in a room at a certain time."},{"name":"Lucas","text":"I disagree. When lectures are online, many students stop coming to class and fall behind because they never actually watch the recordings. Being there in person also makes it possible to ask questions and discuss ideas with classmates."}]},
 {"id":"di02","level":2,"course":"urban planning","professor":{"name":"Dr. Okafor","text":"City governments have limited budgets. Some people argue that money should be spent on improving public transportation, while others think it is more important to create more parks and green spaces. Which do you think should be the priority for city spending, and why?"},
  "students":[{"name":"Sara","text":"Public transportation should come first. Good buses and trains reduce traffic and pollution, and they help people without cars get to jobs and schools."},{"name":"Kevin","text":"I'd choose parks. People need places to relax and exercise, especially in crowded cities. Green spaces also make neighborhoods more attractive and improve mental health."}]},
 {"id":"di03","level":2,"course":"business management","professor":{"name":"Prof. Harris","text":"Some companies have introduced a four-day work week, in which employees work fewer hours for the same pay. Supporters say this increases productivity and well-being; critics say it is not practical for many businesses. Do you think more companies should adopt a four-day work week? Explain your view."},
  "students":[{"name":"Anna","text":"Yes. Studies show that people are more focused when they have more time to rest, so they get the same amount of work done in four days. Companies would also attract better employees."},{"name":"Ben","text":"I'm not convinced. Businesses like hospitals or stores need to be open every day, and fewer working days could mean customers wait longer for service."}]},
 {"id":"di04","level":2,"course":"sociology","professor":{"name":"Dr. Nguyen","text":"Social media allows people to stay in contact with friends and family around the world. However, some researchers argue that it actually makes people feel lonelier. In your opinion, does social media bring people closer together or push them apart? Why?"},
  "students":[{"name":"Emily","text":"It brings people closer. I keep in touch with friends from my hometown every day, which would be impossible without social media."},{"name":"Ryan","text":"I think it pushes people apart. People spend so much time scrolling that they have less time for real conversations with the people around them."}]},
 {"id":"di05","level":2,"course":"environmental science","professor":{"name":"Prof. Garcia","text":"To reduce waste, some cities have banned single-use plastic bags and require stores to charge for paper bags. Other cities prefer education campaigns that encourage people to change their habits voluntarily. Which approach is more effective in reducing waste? Why?"},
  "students":[{"name":"Hannah","text":"Bans work better. People are busy and rarely change their habits unless they have to. After my city banned plastic bags, almost everyone started bringing reusable ones."},{"name":"Omar","text":"I prefer education. Bans can feel unfair, and they don't teach people why reducing waste matters. If people understand the problem, they'll make better choices in many areas, not just with bags."}]},
 {"id":"di06","level":2,"course":"psychology","professor":{"name":"Dr. Brooks","text":"Some people believe students learn best when they study one subject for a long period, while others think it is better to switch between several subjects during a study session. Which approach do you think is more effective for learning? Explain why."},
  "students":[{"name":"Julia","text":"Focusing on one subject for a long time works better for me. I need time to really get into a topic, and switching makes me lose concentration."},{"name":"Marcus","text":"Switching between subjects keeps me fresh. After an hour on the same thing, I stop absorbing information, so changing topics helps me stay alert."}]},
]
data={"bas":[{"id":i,"level":l,"prompt":p,"answer":a,"chunks":c,"why":w} for i,l,p,a,c,w in BAS],"email":EMAIL,"discussion":DISC}
json.dump(data,open("/home/claude/toefl-karteikarten/trainer/content/writing.json","w"),ensure_ascii=False,indent=1)
print(len(data["bas"]),len(EMAIL),len(DISC))
